import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.BPmc_f4o.js";const g=JSON.parse('{"title":"tecs.gfx.layers","description":"Layer bands, the depth they resolve to, and what a layer does to its contents: sorting, positioning, parallax and lighting","frontmatter":{"description":"Layer bands, the depth they resolve to, and what a layer does to its contents: sorting, positioning, parallax and lighting","outline":"deep"},"headers":[],"relativePath":"modules/gfx/layers.md","filePath":"modules/gfx/layers.md"}'),r={name:"modules/gfx/layers.md"};function o(n,e,h,d,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /modules/gfx/layers.md for this page in Markdown format</div><h1 id="tecs-gfx-layers" tabindex="-1">tecs.gfx.layers <a class="header-anchor" href="#tecs-gfx-layers" aria-label="Permalink to &quot;tecs.gfx.layers&quot;">​</a></h1><p>A layer is a band of the depth range. Everything drawn on a layer sorts within that band and never against another one, so a HUD on layer 8 covers a world on layer 1 whatever the two contain. A layer is what a <code>Transform</code> carries alongside its position, and it defaults to one.</p><p>The band formula is fixed rather than configurable. Content is authored against what it produces: change how a layer maps to depth and every scene built on it re-sorts, which is a change nobody can see coming from the diff. What a layer does configure is how its contents sort within its own band, where they are positioned, and whether they are lit. Those decide where a game puts a thing, so they are settled before content is authored rather than after: whether a layer is screen-space is the difference between a HUD written in pixels and one written in world units.</p><h2 id="module-values" tabindex="-1">Module values <a class="header-anchor" href="#module-values" aria-label="Permalink to &quot;Module values&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Type</th><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>MAX</code></td><td><code>integer</code></td><td><code>16</code></td><td>Bands the depth range divides into, and the highest layer index.</td></tr><tr><td><code>maxZ</code></td><td><code>number</code></td><td><code>1000</code></td><td>Highest z a scene is expected to use, which sets the resolution of sorting within a band.</td></tr><tr><td><code>maxY</code></td><td><code>number</code></td><td><code>10000</code></td><td>Half the world extent a scene is expected to occupy, for normalising position into a band.</td></tr><tr><td><code>virtualWidth</code></td><td><code>number</code></td><td><code>1920</code></td><td>Width of the resolution a virtual-coordinate layer is authored in.</td></tr><tr><td><code>virtualHeight</code></td><td><code>number</code></td><td><code>1080</code></td><td>Height of that resolution.</td></tr></tbody></table><p><code>MAX</code> is load-bearing at sixteen. A sort mode packs into two bits, the table the vertex shader reads is sized to it, and the shader recovers a layer by multiplying a depth by it. <code>LAYER_BANDS</code> in <code>assets/shaders/instance.vert.glsl</code> is the same number, and the two only work while they agree. Raising it is not a constant change.</p><p>A scene reaching past <code>maxZ</code> still draws, with entities beyond the edge resting on it and no longer sorting against each other. A scene larger than <code>maxY</code> still sorts, with entities beyond the edge compressed against it.</p><p>There is one virtual resolution for every virtual-coordinate layer, because it is the design size a layout is drawn against and a game has one of those. It is scaled to fill the target, so the layout keeps its proportions within itself at any window size and stretches with the window&#39;s aspect.</p><h2 id="sort-modes" tabindex="-1">Sort modes <a class="header-anchor" href="#sort-modes" aria-label="Permalink to &quot;Sort modes&quot;">​</a></h2><p><code>layers.Sort</code> is an enum of three strings.</p><table tabindex="0"><thead><tr><th>Sort</th><th>What decides the order within the band</th></tr></thead><tbody><tr><td><code>&quot;topdown&quot;</code></td><td>World y and z together: lower on the screen draws in front of what is above it, and z carries the greater share of the band, so a character standing on a crate reads as on top of it. What a top-down or side-on game wants.</td></tr><tr><td><code>&quot;z&quot;</code></td><td>Only z. What a HUD wants, where position means nothing and the author has said what covers what.</td></tr><tr><td><code>&quot;isometric&quot;</code></td><td>World x plus world y plus z, for a diamond grid where both axes move an entity towards the viewer.</td></tr></tbody></table><h2 id="configuring-a-layer" tabindex="-1">Configuring a layer <a class="header-anchor" href="#configuring-a-layer" aria-label="Permalink to &quot;Configuring a layer&quot;">​</a></h2><h3 id="configure" tabindex="-1">configure <a class="header-anchor" href="#configure" aria-label="Permalink to &quot;configure&quot;">​</a></h3><p>Sets what a layer does with its contents.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> layers</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">configure</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(layer: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">integer</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, config: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">layers</span><span style="--shiki-light:#0E1116;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">Config</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">)</span></span></code></pre></div><p><strong>Parameters:</strong></p><ul><li><code>layer</code>: one to <code>MAX</code>. Anything else raises.</li><li><code>config</code>: the whole of what the layer is. Raises on a missing or unknown <code>sort</code>, and on asking for <code>screenSpace</code> and <code>virtualCoords</code> together.</li></ul><div class="warning custom-block"><p class="custom-block-title">Replaces, never amends</p><p>A <code>Config</code> is the whole of what a layer is, so a field left out is that field&#39;s default and not whatever the layer held before. This says what a layer is rather than amending what it was.</p></div><p><strong><code>Config</code> fields:</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>sort</code></td><td><code>layers.Sort</code></td><td>required</td><td>How contents sort within the layer&#39;s band. A sort is the one thing every layer has an opinion about.</td></tr><tr><td><code>screenSpace</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Contents are positioned in screen pixels and ignore the camera entirely. What a HUD wants.</td></tr><tr><td><code>ignoreZoom</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Contents follow the camera&#39;s position but not its zoom, so they stay a constant size on screen while moving with the world.</td></tr><tr><td><code>virtualCoords</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Contents are positioned in <code>virtualWidth</code> by <code>virtualHeight</code>, which is scaled to fill the target. Cannot be combined with <code>screenSpace</code>.</td></tr><tr><td><code>unlit</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Contents bypass the lighting pass and appear at their own colour.</td></tr><tr><td><code>parallax</code></td><td><code>number</code></td><td><code>1</code></td><td>How much the camera&#39;s position carries the contents. One moves them with the world; a half drifts them at half speed, which is what a background wants.</td></tr></tbody></table><p>A material can also ask to be unlit, and a fragment is lit only where the material and the layer agree.</p><p><strong>Example:</strong></p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">tecs.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">gfx</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">layers</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">configure</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(</span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">1</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, { </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">sort </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECE6A;">topdown</span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">parallax </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">0.5</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;"> })</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">tecs.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">gfx</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">layers</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">configure</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(</span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">2</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, { </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">sort </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECE6A;">topdown</span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;"> })</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">tecs.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">gfx</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">layers</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">configure</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(</span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">8</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, { </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">sort </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECE6A;">z</span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">screenSpace </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">true</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">unlit </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">true</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;"> })</span></span></code></pre></div><h2 id="culling" tabindex="-1">Culling <a class="header-anchor" href="#culling" aria-label="Permalink to &quot;Culling&quot;">​</a></h2><p>The cull tests a world bound against the world rectangle the camera sees, which only means something on a layer the camera places where that bound says. Screen-space and virtual-coordinate contents have no world position for the view to test, and parallax and ignore-zoom draw them somewhere the bound does not describe.</p><p>Extraction reads <code>viewCulled</code> per row and writes a bound no view can be outside of for those layers, so the layer is drawn whatever the camera is looking at. Culling is given up on a layer that asks for one of these, and kept exactly on every layer that does not, which is where the entities are.</p><h3 id="viewculled" tabindex="-1">viewCulled <a class="header-anchor" href="#viewculled" aria-label="Permalink to &quot;viewCulled&quot;">​</a></h3><p>Whether the camera&#39;s view rectangle decides if this layer is drawn.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> layers</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">viewCulled</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(layer: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">integer</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">): </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">boolean</span></span></code></pre></div><p><strong>Parameters:</strong></p><ul><li><code>layer</code>: one to <code>MAX</code>. Outside that this answers true, which is what an unconfigured layer answers too.</li></ul><p><strong>Returns:</strong> whether extraction should write this row&#39;s real world bound. False on a layer positioned in screen pixels or virtual coordinates, on one with a parallax other than one, and on one that ignores zoom.</p><h2 id="depth" tabindex="-1">Depth <a class="header-anchor" href="#depth" aria-label="Permalink to &quot;Depth&quot;">​</a></h2><h3 id="depthof" tabindex="-1">depthOf <a class="header-anchor" href="#depthof" aria-label="Permalink to &quot;depthOf&quot;">​</a></h3><p>Depth for one entity, in zero to one with zero nearest.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> layers</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">depthOf</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(layer: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">integer</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, z: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">number</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, x: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">number</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, y: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">number</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">): </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">number</span></span></code></pre></div><p><strong>Parameters:</strong></p><ul><li><code>layer</code>: one to <code>MAX</code>, which picks the band and, through <code>sortOf</code>, what the rest of the arguments mean. Outside that range this takes the nearest layer whole and goes on sorting within it, because a band is the only thing a depth can name.</li><li><code>z</code>: height in the sort, against <code>maxZ</code>. Read by every sort mode.</li><li><code>x</code>: world x, read only by the isometric sort, against <code>maxY</code>.</li><li><code>y</code>: world y, read by the topdown and isometric sorts, against <code>maxY</code>. Larger is lower on screen and so nearer.</li></ul><p><strong>Returns:</strong> a depth inside the layer&#39;s own band, whatever the arguments were. Each of them is normalised and then held to zero and one, so a scene reaching past what the module was told to expect stops sorting rather than spilling into the next layer.</p><p>Higher layers are nearer, so layer <code>MAX</code> occupies the band closest to zero. A sliver is left at the end of each band, so the far end of one never reaches the near end of the next.</p><div class="info custom-block"><p class="custom-block-title">Exact ties carry no tie-breaker</p><p>Instances are drawn in index order and the depth test lets an equal fragment through, so two entities at the same depth already resolve the same way every frame: the later one wins. Nudging depth by identity would resolve them the other way, since a larger value is farther, and quietly invert the order a scene was built expecting.</p></div><h3 id="depthresolution" tabindex="-1">depthResolution <a class="header-anchor" href="#depthresolution" aria-label="Permalink to &quot;depthResolution&quot;">​</a></h3><p>The smallest depth difference <code>depthOf</code> produces between two entities one unit apart, taken over every sort mode.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> layers</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">depthResolution</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(): </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">number</span></span></code></pre></div><p><strong>Returns:</strong> a depth difference, in the input that moves depth least. That is the topdown sort&#39;s y at the defaults, which spends the smallest share of a band on the widest range.</p><p>This is what a depth buffer has to hold. A format whose own step is larger than this keeps the bands, so layer order is never at risk, and loses the sort inside them: the two entities land on one depth value and draw in the order they were written rather than the order they were sorted into.</p><p>Every mode is counted rather than the one a scene is using, because <code>configure</code> may put any layer on any sort at any point after the depth target exists. The number is derived from <code>MAX</code>, <code>maxZ</code> and <code>maxY</code>, so raising an extent moves it.</p><p>What a device&#39;s depth target holds is the other half of that comparison, and <a href="/modules/gfx/#tecs.gfx.Renderer.depthSortCollapse"><code>Renderer:depthSortCollapse</code></a> is what makes the two answerable: it reports the world units that collapse onto one depth value there, which is the factor <code>maxY</code> and <code>maxZ</code> divide by to resolve the sort again.</p><h2 id="reading-the-table-back" tabindex="-1">Reading the table back <a class="header-anchor" href="#reading-the-table-back" aria-label="Permalink to &quot;Reading the table back&quot;">​</a></h2><p>These three are what the renderer packs into the uniform the vertex shader reads. A game rarely calls them, and they are here because the table is public.</p><h3 id="sortof" tabindex="-1">sortOf <a class="header-anchor" href="#sortof" aria-label="Permalink to &quot;sortOf&quot;">​</a></h3><p>How a layer sorts, as the identifier <code>depthOf</code> takes.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> layers</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">sortOf</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(layer: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">integer</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">): </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">integer</span></span></code></pre></div><p><strong>Parameters:</strong></p><ul><li><code>layer</code>: one to <code>MAX</code>. Outside that this answers topdown rather than raising, since it is the default every layer starts on.</li></ul><p><strong>Returns:</strong> the sort identifier, which is an internal number and not one of the <code>Sort</code> strings.</p><h3 id="entryof" tabindex="-1">entryOf <a class="header-anchor" href="#entryof" aria-label="Permalink to &quot;entryOf&quot;">​</a></h3><p>The four floats the vertex shader reads for one layer.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> layers</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">entryOf</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(layer: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">integer</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">): </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">number</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">number</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">number</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">number</span></span></code></pre></div><p><strong>Parameters:</strong></p><ul><li><code>layer</code>: one to <code>MAX</code>. Outside that every return is nil, since only that range is ever filled in.</li></ul><p><strong>Returns:</strong> the positioning mode, then the camera position&#39;s multiplier, which is one minus <code>parallax</code>, then one when the layer ignores zoom, then one when it is lit.</p><p>They are handed over as a group because they are packed as a group, which happens when <code>revision</code> moves rather than every frame.</p><h3 id="revision" tabindex="-1">revision <a class="header-anchor" href="#revision" aria-label="Permalink to &quot;revision&quot;">​</a></h3><p>How many times the table has been configured.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> layers</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">revision</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(): </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">integer</span></span></code></pre></div><p><strong>Returns:</strong> a count that starts at zero and only rises. A consumer compares it against the value it packed at, so the number itself means nothing beyond having changed.</p><h2 id="clipping-is-a-separate-opt-in" tabindex="-1">Clipping is a separate opt-in <a class="header-anchor" href="#clipping-is-a-separate-opt-in" aria-label="Permalink to &quot;Clipping is a separate opt-in&quot;">​</a></h2><p>A layer decides where its contents are placed and how they sort; it does not bound them. Keeping an entity&#39;s fragments inside a rectangle is the <code>Clip</code> component, whose index names a rectangle set through the <a href="/modules/gfx/">Renderer</a>. Zero, the default, means no clipping, and a world that clips nothing pays for it exactly nowhere.</p><p>The rectangle is in target pixels and is tested against the fragment&#39;s own position, which is what a scrollable list inside a panel means and is right for world contents and screen-space layers alike. It is not a world rectangle, so it does not move with the camera.</p><p>Regions do not nest. A region is one rectangle, so a panel inside a panel is set up as the intersection of the two and the fragment tests once. <code>Renderer:clearClipRegion</code> puts a region back to clipping nothing rather than to clipping everything out, so an index handed out and taken back leaves instances still pointing at it drawing whole instead of silently vanishing.</p><p>The cull knows nothing about regions. An instance entirely outside its region is still drawn and then thrown away a fragment at a time, which is correct and wasteful; keeping a clipped thing off screen is worth doing with a layer or a position rather than with a large region.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><p>Every function and type this module carries, rendered from <code>src/tecs/gfx/layers.tl</code>.</p><p><a id="tecs.gfx.layers.Config"></a></p><h3 id="tecs-gfx-layers-config" tabindex="-1">tecs.gfx.layers.Config <a class="header-anchor" href="#tecs-gfx-layers-config" aria-label="Permalink to &quot;tecs.gfx.layers.Config&quot;">​</a></h3><pre><code>record <a href="#tecs.gfx.layers.Config">tecs.gfx.layers.Config</a>
</code></pre><p>Everything a layer decides about its contents. A field left out takes its default, so this says what a layer is rather than amending what it was. <a id="tecs.gfx.layers.Config.sort"></a></p><h3 id="tecs-gfx-layers-config-sort" tabindex="-1">tecs.gfx.layers.Config.sort <a class="header-anchor" href="#tecs-gfx-layers-config-sort" aria-label="Permalink to &quot;tecs.gfx.layers.Config.sort&quot;">​</a></h3><pre><code><a href="#tecs.gfx.layers.Config.sort">tecs.gfx.layers.Config.sort</a>: <a href="#tecs.gfx.layers.Sort">Sort</a>
</code></pre><p>How contents sort within the layer&#39;s band. Required: a sort is the one thing every layer has an opinion about. <a id="tecs.gfx.layers.Config.screenSpace"></a></p><h3 id="tecs-gfx-layers-config-screenspace" tabindex="-1">tecs.gfx.layers.Config.screenSpace <a class="header-anchor" href="#tecs-gfx-layers-config-screenspace" aria-label="Permalink to &quot;tecs.gfx.layers.Config.screenSpace&quot;">​</a></h3><pre><code><a href="#tecs.gfx.layers.Config.screenSpace">tecs.gfx.layers.Config.screenSpace</a>: boolean
</code></pre><p>Contents are positioned in screen pixels and ignore the camera entirely. What a HUD wants. Defaults to false. <a id="tecs.gfx.layers.Config.ignoreZoom"></a></p><h3 id="tecs-gfx-layers-config-ignorezoom" tabindex="-1">tecs.gfx.layers.Config.ignoreZoom <a class="header-anchor" href="#tecs-gfx-layers-config-ignorezoom" aria-label="Permalink to &quot;tecs.gfx.layers.Config.ignoreZoom&quot;">​</a></h3><pre><code><a href="#tecs.gfx.layers.Config.ignoreZoom">tecs.gfx.layers.Config.ignoreZoom</a>: boolean
</code></pre><p>Contents follow the camera&#39;s position but not its zoom, so they stay a constant size on screen while moving with the world. Defaults to false. <a id="tecs.gfx.layers.Config.virtualCoords"></a></p><h3 id="tecs-gfx-layers-config-virtualcoords" tabindex="-1">tecs.gfx.layers.Config.virtualCoords <a class="header-anchor" href="#tecs-gfx-layers-config-virtualcoords" aria-label="Permalink to &quot;tecs.gfx.layers.Config.virtualCoords&quot;">​</a></h3><pre><code><a href="#tecs.gfx.layers.Config.virtualCoords">tecs.gfx.layers.Config.virtualCoords</a>: boolean
</code></pre><p>Contents are positioned in <code>virtualWidth</code> by <code>virtualHeight</code>, which is scaled to fill the target. Defaults to false, and cannot be combined with <code>screenSpace</code>. <a id="tecs.gfx.layers.Config.unlit"></a></p><h3 id="tecs-gfx-layers-config-unlit" tabindex="-1">tecs.gfx.layers.Config.unlit <a class="header-anchor" href="#tecs-gfx-layers-config-unlit" aria-label="Permalink to &quot;tecs.gfx.layers.Config.unlit&quot;">​</a></h3><pre><code><a href="#tecs.gfx.layers.Config.unlit">tecs.gfx.layers.Config.unlit</a>: boolean
</code></pre><p>Contents bypass the lighting pass and appear at their own colour. Defaults to false. A material can ask for the same thing, and a fragment is lit only where the material and the layer agree. <a id="tecs.gfx.layers.Config.parallax"></a></p><h3 id="tecs-gfx-layers-config-parallax" tabindex="-1">tecs.gfx.layers.Config.parallax <a class="header-anchor" href="#tecs-gfx-layers-config-parallax" aria-label="Permalink to &quot;tecs.gfx.layers.Config.parallax&quot;">​</a></h3><pre><code><a href="#tecs.gfx.layers.Config.parallax">tecs.gfx.layers.Config.parallax</a>: number
</code></pre><p>How much the camera&#39;s position carries the contents. One moves them with the world; a half drifts them at half speed, which is what a background wants. Defaults to one. <a id="tecs.gfx.layers.MAX"></a></p><h3 id="tecs-gfx-layers-max" tabindex="-1">tecs.gfx.layers.MAX <a class="header-anchor" href="#tecs-gfx-layers-max" aria-label="Permalink to &quot;tecs.gfx.layers.MAX&quot;">​</a></h3><pre><code><a href="#tecs.gfx.layers.MAX">tecs.gfx.layers.MAX</a>: integer
</code></pre><p>Bands the depth range divides into.</p><p>Load-bearing at sixteen. A sort mode packs into two bits, the table the vertex shader reads is sized to it, and the shader recovers a layer by multiplying a depth by it. <code>LAYER_BANDS</code> in <code>assets/shaders/instance.vert.glsl</code> is the same number, and the two only work while they agree. Raising it is not a constant change. <a id="tecs.gfx.layers.Sort"></a></p><h3 id="tecs-gfx-layers-sort" tabindex="-1">tecs.gfx.layers.Sort <a class="header-anchor" href="#tecs-gfx-layers-sort" aria-label="Permalink to &quot;tecs.gfx.layers.Sort&quot;">​</a></h3><pre><code>enum <a href="#tecs.gfx.layers.Sort">tecs.gfx.layers.Sort</a>
</code></pre><p><a id="tecs.gfx.layers.Sort.&quot;isometric&quot;"></a></p><h3 id="tecs-gfx-layers-sort-quot-isometric-quot" tabindex="-1">tecs.gfx.layers.Sort.&quot;isometric&quot; <a class="header-anchor" href="#tecs-gfx-layers-sort-quot-isometric-quot" aria-label="Permalink to &quot;tecs.gfx.layers.Sort.&amp;quot;isometric&amp;quot;&quot;">​</a></h3><p>X plus Y plus z, for a diamond grid where both axes move an entity towards the viewer. <a id="tecs.gfx.layers.Sort.&quot;topdown&quot;"></a></p><h3 id="tecs-gfx-layers-sort-quot-topdown-quot" tabindex="-1">tecs.gfx.layers.Sort.&quot;topdown&quot; <a class="header-anchor" href="#tecs-gfx-layers-sort-quot-topdown-quot" aria-label="Permalink to &quot;tecs.gfx.layers.Sort.&amp;quot;topdown&amp;quot;&quot;">​</a></h3><p>Lower on the screen draws in front, with z breaking ties. What a top-down or side-on game wants: a character below a crate is in front of it. <a id="tecs.gfx.layers.Sort.&quot;z&quot;"></a></p><h3 id="tecs-gfx-layers-sort-quot-z-quot" tabindex="-1">tecs.gfx.layers.Sort.&quot;z&quot; <a class="header-anchor" href="#tecs-gfx-layers-sort-quot-z-quot" aria-label="Permalink to &quot;tecs.gfx.layers.Sort.&amp;quot;z&amp;quot;&quot;">​</a></h3><p>Only z decides. What a HUD wants, where position means nothing and the author has said what covers what. <a id="tecs.gfx.layers.configure"></a></p><h3 id="tecs-gfx-layers-configure" tabindex="-1">tecs.gfx.layers.configure <a class="header-anchor" href="#tecs-gfx-layers-configure" aria-label="Permalink to &quot;tecs.gfx.layers.configure&quot;">​</a></h3><pre><code>function <a href="#tecs.gfx.layers.configure">tecs.gfx.layers.configure</a>(layer: integer, config: layers.Config)
</code></pre><p>Sets what a layer does with its contents.</p><p>Replaces the layer&#39;s configuration rather than amending it: a <code>Config</code> is the whole of what a layer is, so a field left out is that field&#39;s default and not whatever the layer held before.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>integer</code></td><td><code>layer</code></td><td>One to <code>MAX</code>. Anything else raises.</td></tr><tr><td><code>layers.Config</code></td><td><code>config</code></td><td>Raises on a missing or unknown <code>sort</code>, and on asking for <code>screenSpace</code> and <code>virtualCoords</code> together.</td></tr></tbody></table><p><a id="tecs.gfx.layers.depthOf"></a></p><h3 id="tecs-gfx-layers-depthof" tabindex="-1">tecs.gfx.layers.depthOf <a class="header-anchor" href="#tecs-gfx-layers-depthof" aria-label="Permalink to &quot;tecs.gfx.layers.depthOf&quot;">​</a></h3><pre><code>function <a href="#tecs.gfx.layers.depthOf">tecs.gfx.layers.depthOf</a>(layer: integer, z: number, x: number, y: number): number
</code></pre><p>Depth for one entity, in zero to one with zero nearest.</p><p>Exact ties carry no tie-breaker. Instances are drawn in index order and the depth test lets an equal fragment through, so two entities at the same depth already resolve the same way every frame: the later one wins. Nudging depth by identity would resolve them the other way, since a larger value is farther, and quietly invert the order a scene was built expecting.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>integer</code></td><td><code>layer</code></td><td>One to <code>MAX</code>, which picks the band and, through <code>sortOf</code>, what the rest of the arguments mean. Outside that range this takes the nearest layer whole and goes on sorting within it, because a band is the only thing a depth can name.</td></tr><tr><td><code>number</code></td><td><code>z</code></td><td>Height in the sort, against <code>maxZ</code>. Read by every sort mode.</td></tr><tr><td><code>number</code></td><td><code>x</code></td><td>World x, read only by the isometric sort, against <code>maxY</code>.</td></tr><tr><td><code>number</code></td><td><code>y</code></td><td>World y, read by the topdown and isometric sorts, against <code>maxY</code>. Larger is lower on screen and so nearer.</td></tr></tbody></table><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>number</code></td><td>A depth inside the layer&#39;s own band, whatever the arguments were: each of them is normalised and then held to zero and one, so a scene reaching past what the module was told to expect stops sorting rather than spilling into the next layer.</td></tr></tbody></table><p><a id="tecs.gfx.layers.depthResolution"></a></p><h3 id="tecs-gfx-layers-depthresolution" tabindex="-1">tecs.gfx.layers.depthResolution <a class="header-anchor" href="#tecs-gfx-layers-depthresolution" aria-label="Permalink to &quot;tecs.gfx.layers.depthResolution&quot;">​</a></h3><pre><code>function <a href="#tecs.gfx.layers.depthResolution">tecs.gfx.layers.depthResolution</a>(): number
</code></pre><p>The smallest depth difference <code>depthOf</code> produces between two entities one unit apart, taken over every sort mode.</p><p>What a depth buffer has to hold. A format whose own step is larger than this keeps the bands, so layer order is never at risk, and loses the sort inside them: the two entities land on one depth value and draw in the order they were written rather than the order they were sorted into.</p><p>Every mode is counted rather than the one a scene is using, because <code>configure</code> may put any layer on any sort at any point after the depth target exists. Derived from <code>MAX</code>, <code>maxZ</code> and <code>maxY</code>, so raising an extent moves this with it.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>number</code></td><td>A depth difference, in the input that moves depth least. That is the topdown sort&#39;s y at the defaults, which spends the smallest share of a band on the widest range.</td></tr></tbody></table><p><a id="tecs.gfx.layers.entryOf"></a></p><h3 id="tecs-gfx-layers-entryof" tabindex="-1">tecs.gfx.layers.entryOf <a class="header-anchor" href="#tecs-gfx-layers-entryof" aria-label="Permalink to &quot;tecs.gfx.layers.entryOf&quot;">​</a></h3><pre><code>function <a href="#tecs.gfx.layers.entryOf">tecs.gfx.layers.entryOf</a>(layer: integer): number, number, number, number
</code></pre><p>The four floats the vertex shader reads for one layer: its mode, its parallax offset factor, whether it ignores zoom, and whether it is lit.</p><p>Handed over as a group because they are packed as a group, which happens when <code>revision</code> moves rather than every frame.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>integer</code></td><td><code>layer</code></td><td>One to <code>MAX</code>. Outside that every return is nil, since only that range is ever filled in.</td></tr></tbody></table><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>number</code></td><td>The positioning mode, then the camera position&#39;s multiplier, then one when the layer ignores zoom, then one when it is lit.</td></tr><tr><td><code>number</code></td><td></td></tr><tr><td><code>number</code></td><td></td></tr><tr><td><code>number</code></td><td></td></tr></tbody></table><p><a id="tecs.gfx.layers.maxY"></a></p><h3 id="tecs-gfx-layers-maxy" tabindex="-1">tecs.gfx.layers.maxY <a class="header-anchor" href="#tecs-gfx-layers-maxy" aria-label="Permalink to &quot;tecs.gfx.layers.maxY&quot;">​</a></h3><pre><code><a href="#tecs.gfx.layers.maxY">tecs.gfx.layers.maxY</a>: number
</code></pre><p>Half the world extent a scene is expected to occupy, for normalising position into a band. A scene larger than this still sorts, with entities beyond the edge compressed against it. <a id="tecs.gfx.layers.maxZ"></a></p><h3 id="tecs-gfx-layers-maxz" tabindex="-1">tecs.gfx.layers.maxZ <a class="header-anchor" href="#tecs-gfx-layers-maxz" aria-label="Permalink to &quot;tecs.gfx.layers.maxZ&quot;">​</a></h3><pre><code><a href="#tecs.gfx.layers.maxZ">tecs.gfx.layers.maxZ</a>: number
</code></pre><p>Highest z a scene is expected to use, which sets the resolution of sorting within a band. A scene reaching past this still draws, with entities beyond the edge resting on it and no longer sorting against each other. <a id="tecs.gfx.layers.revision"></a></p><h3 id="tecs-gfx-layers-revision" tabindex="-1">tecs.gfx.layers.revision <a class="header-anchor" href="#tecs-gfx-layers-revision" aria-label="Permalink to &quot;tecs.gfx.layers.revision&quot;">​</a></h3><pre><code>function <a href="#tecs.gfx.layers.revision">tecs.gfx.layers.revision</a>(): integer
</code></pre><p>How many times the table has been configured.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>integer</code></td><td>A count that starts at zero and only rises. A consumer compares it against the value it packed at, so the number itself means nothing beyond having changed.</td></tr></tbody></table><p><a id="tecs.gfx.layers.sortOf"></a></p><h3 id="tecs-gfx-layers-sortof" tabindex="-1">tecs.gfx.layers.sortOf <a class="header-anchor" href="#tecs-gfx-layers-sortof" aria-label="Permalink to &quot;tecs.gfx.layers.sortOf&quot;">​</a></h3><pre><code>function <a href="#tecs.gfx.layers.sortOf">tecs.gfx.layers.sortOf</a>(layer: integer): integer
</code></pre><p>How a layer sorts, as the identifier <code>depthOf</code> takes.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>integer</code></td><td><code>layer</code></td><td>One to <code>MAX</code>. Outside that this answers topdown rather than raising, since it is the default every layer starts on.</td></tr></tbody></table><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>integer</code></td><td>The sort identifier, which is an internal number and not one of the <code>Sort</code> strings.</td></tr></tbody></table><p><a id="tecs.gfx.layers.viewCulled"></a></p><h3 id="tecs-gfx-layers-viewculled" tabindex="-1">tecs.gfx.layers.viewCulled <a class="header-anchor" href="#tecs-gfx-layers-viewculled" aria-label="Permalink to &quot;tecs.gfx.layers.viewCulled&quot;">​</a></h3><pre><code>function <a href="#tecs.gfx.layers.viewCulled">tecs.gfx.layers.viewCulled</a>(layer: integer): boolean
</code></pre><p>Whether the camera&#39;s view rectangle decides if this layer is drawn.</p><p>False on a layer the camera does not place where its world bound says: screen-space and virtual-coordinate contents have no world position for the view to test, and parallax and ignore-zoom draw them somewhere the bound does not describe. Extraction reads this per row and writes a bound no view can be outside of for those, so the layer is drawn whatever the camera is looking at. Culling is given up on a layer that asks for one of these, and kept exactly on every layer that does not.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>integer</code></td><td><code>layer</code></td><td>One to <code>MAX</code>. Outside that this answers true, which is what an unconfigured layer answers too.</td></tr></tbody></table><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>boolean</code></td><td>Whether extraction should write this row&#39;s real world bound.</td></tr></tbody></table><p><a id="tecs.gfx.layers.virtualHeight"></a></p><h3 id="tecs-gfx-layers-virtualheight" tabindex="-1">tecs.gfx.layers.virtualHeight <a class="header-anchor" href="#tecs-gfx-layers-virtualheight" aria-label="Permalink to &quot;tecs.gfx.layers.virtualHeight&quot;">​</a></h3><pre><code><a href="#tecs.gfx.layers.virtualHeight">tecs.gfx.layers.virtualHeight</a>: number
</code></pre><p><a id="tecs.gfx.layers.virtualWidth"></a></p><h3 id="tecs-gfx-layers-virtualwidth" tabindex="-1">tecs.gfx.layers.virtualWidth <a class="header-anchor" href="#tecs-gfx-layers-virtualwidth" aria-label="Permalink to &quot;tecs.gfx.layers.virtualWidth&quot;">​</a></h3><pre><code><a href="#tecs.gfx.layers.virtualWidth">tecs.gfx.layers.virtualWidth</a>: number
</code></pre><p>The resolution a virtual-coordinate layer is authored in.</p><p>One resolution for every such layer, because it is the design size a layout is drawn against and a game has one of those. It is scaled to fill the target, so the layout keeps its proportions within itself at any window size and stretches with the window&#39;s aspect.</p>`,179)])])}const y=t(r,[["render",o]]);export{g as __pageData,y as default};
